insert into ideas (id, topic_id, source_id, title, body) values
  ('two-minute-rule', 'productivity', 'gtd', 'The two-minute rule', 'If a task takes less than two minutes, do it now. Writing it down, tracking it and coming back to it later costs more attention than simply finishing it. Small tasks left undone pile up into a background hum of stress.'),
  ('eat-the-frog', 'productivity', 'eat-that-frog', 'Eat the frog first', 'Start your day with the hardest, most important task, the one you are most likely to put off. Once it is done, everything else feels lighter, and you have already won the day before distractions arrive.'),
  ('parkinsons-law', 'productivity', 'parkinsons-law', 'Work expands to fill the time', 'A task given a week will take a week; the same task given an afternoon often gets done in an afternoon. Setting tighter, deliberate deadlines forces you to focus on what actually matters and skip the polishing nobody asked for.'),
  ('deep-work', 'productivity', 'deep-work', 'Protect blocks of deep work', 'Valuable work, like learning hard things or creating something new, needs long stretches of undistracted focus. Schedule those blocks like meetings, close the inbox and silence the phone. Shallow busywork can fill the gaps around them.'),
  ('habit-stacking', 'psychology', 'atomic-habits', 'Stack new habits on old ones', 'Attach a habit you want to an existing routine: "After I pour my morning coffee, I will write one sentence in my journal." The old habit becomes a reliable cue, so you no longer depend on remembering or on motivation.'),
  ('one-percent', 'psychology', 'atomic-habits', 'Tiny gains compound', 'Getting 1% better each day barely shows at first, but small improvements compound like interest. Focus on the system you follow every day rather than the goal; results are a lagging measure of your habits.'),
  ('system-1-2', 'psychology', 'thinking-fast-slow', 'Two systems of thinking', 'System 1 is fast, automatic and intuitive. System 2 is slow, effortful and logical. Most errors happen when System 1 answers a question that needed System 2. For decisions that matter, slow down and check your first impression.'),
  ('dichotomy-of-control', 'philosophy', 'enchiridion', 'Separate what you control', 'Some things are up to us, our judgments, choices and efforts, and some are not, like other people''s opinions or the weather. Peace comes from putting your energy into the first group and accepting the second.'),
  ('memento-mori', 'philosophy', 'meditations', 'Remember that you will die', 'The Stoics reminded themselves daily that life is short. Not to be gloomy, but to sharpen priorities: if today were among your last, would petty grudges or endless scrolling still feel worth it?'),
  ('name-the-emotion', 'mindfulness', 'affect-labeling', 'Name it to tame it', 'Simply putting a feeling into words, "I feel anxious", reduces activity in the brain''s alarm system. Labeling an emotion creates a little distance between you and it, which gives you room to choose a response.'),
  ('beginners-mind', 'mindfulness', 'zen-mind', 'Keep a beginner''s mind', 'In the beginner''s mind there are many possibilities; in the expert''s mind there are few. Approach familiar things with curiosity, as if seeing them for the first time, and you will notice what habit hides.'),
  ('pay-yourself-first', 'money', 'babylon', 'Pay yourself first', 'Before paying anyone else, set aside a fixed part of everything you earn, even a tenth. Treat it as a bill owed to your future self. Saving what is left at the end of the month rarely works, because little is ever left.'),
  ('compounding-time', 'money', 'psychology-of-money', 'Compounding needs time, not genius', 'Most long-term wealth comes from earning decent returns for a very long time without interruption. Avoiding ruin and staying invested through bad years matters more than finding the highest return.'),
  ('sleep-performance', 'health', 'why-we-sleep', 'Sleep is a performance tool', 'Sleep is when the brain files memories and clears waste. Regularly sleeping six hours or less hurts focus, mood and immunity, often without you noticing. Keeping a consistent wake time is one of the simplest health upgrades.'),
  ('walk-to-think', 'health', 'walking-study', 'Walk to think better', 'In Stanford experiments, people came up with more creative ideas while walking than while sitting, and the boost lasted shortly after they sat back down. Stuck on a problem? Take it for a walk.'),
  ('steal-like-an-artist', 'creativity', 'steal-like-an-artist', 'Nothing is completely original', 'Every creative work builds on what came before. Collect influences, study them, remix them and add your own twist. Copying one source is plagiarism; combining many and transforming them is how style is born.'),
  ('resistance', 'creativity', 'war-of-art', 'Beat Resistance by showing up', 'The force that keeps you from your creative work, procrastination, self-doubt, sudden urges to do chores, is strongest right before something important. Professionals don''t wait for inspiration; they sit down every day and do the work.'),
  ('start-with-why', 'leadership', 'start-with-why', 'Start with why', 'Most organizations explain what they do and how they do it. Inspiring leaders start with why: the purpose or belief behind the work. People don''t just buy what you do; they buy into why you do it.'),
  ('extreme-ownership', 'leadership', 'extreme-ownership', 'Own everything in your world', 'When something goes wrong, a good leader doesn''t blame the team, the plan or bad luck. They take responsibility, find what they could have done better and fix it. That ownership spreads through the whole team.')
